using sv_79a32f4479784b358bdb7274834490ab.Client.Services;

namespace sv_79a32f4479784b358bdb7274834490ab.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 8, 30, 0, TimeSpan.FromHours(-5)), Description = "Package picked up", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 10, 14, 15, 0, TimeSpan.FromHours(-5)), Description = "Departed facility", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 11, 6, 45, 0, TimeSpan.FromHours(-6)), Description = "Arrived at sorting center", Location = "Chicago, IL" },
            ]
        },
        ["PKG-002"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 10, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 7, 9, 0, 0, TimeSpan.FromHours(-7)), Description = "Package picked up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 11, 30, 0, TimeSpan.FromHours(-7)), Description = "In transit", Location = "Bakersfield, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 16, 0, 0, TimeSpan.FromHours(-7)), Description = "Out for delivery", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 18, 22, 0, TimeSpan.FromHours(-7)), Description = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 16, 15, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 11, 10, 0, 0, TimeSpan.FromHours(-5)), Description = "Label created", Location = "Dallas, TX" },
            ]
        }
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

